import{c as a,Q as t,j as s,m as r}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Contextual Memory Virtualisation: DAG-Based State Management and Structurally Lossless Trimming for LLM Agents","description":"","frontmatter":{"url":"https://arxiv.org/abs/2602.22402","title":"Contextual Memory Virtualisation: DAG-Based State Management and Structurally Lossless Trimming for LLM Agents","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2602.22402,"authors":["Cosmo Santoni"],"domains":["cs.SE"],"html":"https://arxiv.org/html/2602.22402v1","pdf_path":"pdfs/2602.22402.pdf","published_date":"2026-02-25T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-02-25-contextual-memory-virtualisation-dag-trimming-2602-22402.md","filePath":"research/papers/2026-02-25-contextual-memory-virtualisation-dag-trimming-2602-22402.md","lastUpdated":1785909234000}'),o={name:"research/papers/2026-02-25-contextual-memory-virtualisation-dag-trimming-2602-22402.md"};function i(n,e,l,c,m,u){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="contextual-memory-virtualisation-dag-based-state-management-and-structurally-lossless-trimming-for-llm-agents" tabindex="-1">Contextual Memory Virtualisation: DAG-Based State Management and Structurally Lossless Trimming for LLM Agents <a class="header-anchor" href="#contextual-memory-virtualisation-dag-based-state-management-and-structurally-lossless-trimming-for-llm-agents" aria-label="Permalink to &quot;Contextual Memory Virtualisation: DAG-Based State Management and Structurally Lossless Trimming for LLM Agents&quot;">​</a></h1><p><strong>Authors</strong>: Cosmo Santoni <strong>Published</strong>: February 25, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2602.22402" target="_blank" rel="noreferrer">https://arxiv.org/abs/2602.22402</a> · <a href="https://arxiv.org/html/2602.22402v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2602.22402 <strong>Categories</strong>: cs.SE <strong>PDF</strong>: <a href="https://arxiv.org/abs/2602.22402" target="_blank" rel="noreferrer">research/papers/pdfs/2602.22402.pdf</a> (11 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>As large language models engage in extended reasoning tasks, they accumulate significant state -- architectural mappings, trade-off decisions, codebase conventions -- within the context window. This understanding is lost when sessions reach context limits and undergo lossy compaction. We propose Contextual Memory Virtualisation (CMV), a system that treats accumulated LLM understanding as version-controlled state. Borrowing from operating system virtual memory, CMV models session history as a Directed Acyclic Graph (DAG) with formally defined snapshot, branch, and trim primitives that enable context reuse across independent parallel sessions. We introduce a three-pass structurally lossless trimming algorithm that preserves every user message and assistant response verbatim while reducing token counts by a mean of 20% and up to 86% for sessions with significant overhead by stripping mechanical bloat such as raw tool outputs, base64 images, and metadata. A single-user case-study evaluation across 76 real-world coding sessions demonstrates that trimming remains economically viable under prompt caching, with the strongest gains in mixed tool-use sessions, which average 39% reduction and reach break-even within 10 turns. A reference implementation is available at <a href="https://github.com/CosmoNaught/claude-code-cmv" target="_blank" rel="noreferrer">https://github.com/CosmoNaught/claude-code-cmv</a>.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 CMV（Contextual Memory Virtualisation）：將累積的 LLM 理解視為「版本控制狀態」，借用 OS virtual memory，將 session 歷史建模為 DAG，並定義 snapshot / branch / trim primitive，支援跨獨立平行 session 的 context reuse。</li><li>提出 three-pass structurally lossless trimming 演算法：逐字保留每則 user message 與 assistant response，僅剝除 raw tool output、base64 image、metadata 等 mechanical bloat。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>token 平均減少 20%，高 overhead session 最高減少 86%。</li><li>76 個真實 coding session 的單使用者 case study：prompt caching 下 trimming 仍具經濟性；mixed tool-use session 平均減少 39%，10 turn 內達 break-even。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>文件自述為「single-user case-study」（76 session）；判斷弱點：單一使用者、樣本侷限，泛化性待補；trim 雖 structurally lossless 但剝除 tool output 可能損及後續推理可追溯性。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>高度貼合本庫 context-management：DAG snapshot/branch/trim ≈ /rewind + worktree 平行 session；「逐字保留 user/assistant、只剝 mechanical bloat」正是 compact「delta hint 非全量 rewrite」「file path/error string 原文勿改寫」的精神。</li><li>「prompt caching 下仍經濟、10 turn break-even」直接呼應 context-management 的 Cache 健康指標（cache_read/input_tokens &gt;0.7）。</li><li>參考實作為 <code>claude-code-cmv</code>（Claude Code 生態）→ 與本 workspace 工具鏈天然相容；⚠️ 落地門檻：本庫目前以 markdown handoff + hook 維護狀態，導入 DAG 化 session 管理屬可評估但未驗證的擴充。</li></ul>',16)])])}const g=a(o,[["render",i]]);export{h as __pageData,g as default};
